// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the end-to-end architecture of this onboarding automation.", "HR submits an n8n Form Trigger with only the fields later steps need. The orchestrator validates them with IF and Code nodes, builds a stable hire ID and upserts a Postgres row that stores a status for each task. It then calls sub-workflows through Execute Workflow. The accounts call waits and returns the work email. E-sign runs without waiting, pausing on a Wait node until the provider's webhook arrives. Meetings books first-week sessions and returns their times. A Merge node combines the account and meeting results, and an AI Agent using Vercel AI Gateway drafts the welcome message. HR approves it through a Wait-for-form link before Gmail sends it. Postgres tracks completion, the manager gets a Slack summary, and an error workflow alerts HR-ops."),
    s(5, "How would you design the stable hire ID, and what goes wrong if you get it wrong?", "The ID must be deterministic, so the same hire always produces the same value. I would use an HR or requisition reference if one exists. Otherwise I would hash a normalised personal email: trimmed and lower-cased. I would not include the start date, because start dates change and a changed ID would start a second onboarding. A random UUID or the execution ID per submission is the classic mistake. Every resubmission then looks like a new person, and you get duplicate Workspace users and duplicate e-sign envelopes. The ID becomes the Postgres primary key, and it is passed to every sub-workflow so each one can check or record status. It also appears in alerts so HR-ops can find the record."),
    s(5, "Describe the Postgres data model you would use for tracking onboarding tasks.", "I would use a hires table keyed by hire_id. It holds the submitted fields, the work email once known, an overall status, and created and updated timestamps. A hire_tasks table has one row per hire and task: accounts, esign, meetings, welcome_draft, welcome_approval, welcome_sent and day_one_dm. Each row has a status (pending, in_progress, done or failed), an attempt count, the last error, and external references such as the Workspace user ID, e-sign envelope ID and calendar event IDs. A unique constraint on hire_id plus task makes writes idempotent. Storing the external IDs matters because a rerun can then check or reuse an existing resource instead of creating it again. It also gives HR one status view per hire."),
    s(5, "The requirement says never grant access before it is due. How do you enforce that when accounts are created days ahead?", "Creating the account and granting access are separate steps. The accounts sub-workflow creates the Google Workspace user in a suspended state, or in an organisational unit with no services enabled. It records the user ID and returns the work email, so the welcome message and calendar invites can reference it. Access is activated on the start date. A Schedule-triggered workflow reads Postgres for hires starting today, in their local time zone, and then unsuspends the user and adds the role groups and Slack channels. I would also use the same check as a guard: an IF node refuses activation if the start date is in the future. This means even a manual rerun cannot grant access early."),
    s(4, "Why does the orchestrator wait for the accounts sub-workflow but not for the e-sign sub-workflow?", "The orchestrator needs the work email before it can continue. Meeting invites and the welcome message depend on it, so it must wait for the accounts result. E-sign is different. Its result can take days, because a person has to open and sign the documents, and nothing downstream needs to block on it. If the orchestrator waited, the execution would stay open for days and the welcome message would be held up for no reason. So e-sign runs on its own: it waits on its own Wait node, sends reminders and writes the signed status to Postgres. The manager summary reads that status from the database instead of from the orchestrator's memory."),
    s(4, "How does the e-sign Wait node resume safely on the provider's webhook?", "Before pausing, the sub-workflow sends the envelope to the provider. The callback URL is the execution's $execution.resumeUrl, or the provider's webhook is pointed at a handler that looks up that URL. I store the envelope ID against the hire ID in Postgres. When the callback arrives, I check the provider's signature or a shared secret if the provider supports one. I also confirm that the envelope ID matches the stored record and that the event really means 'completed' and not just 'viewed'. Duplicate callbacks are harmless, because the status update only moves forward. Anything that fails verification is logged and ignored instead of marking documents as signed."),
    s(3, "How would you handle the reminder when the new hire does not sign within the time limit?", "I set the Wait node's limit-wait-time option. If the webhook has not arrived when the limit passes, the execution continues down the timeout path. An IF node checks whether the resume came from the webhook or from the timeout. On a timeout, it re-checks the envelope status with the provider through HTTP Request, in case a callback was lost. If the documents are still unsigned, it sends a reminder and loops back to wait again. A counter in Postgres caps the number of reminders. After the last one, the workflow alerts HR in Slack instead of nagging the candidate forever. Each reminder is recorded so HR can see what was sent and when."),
    s(4, "How do you get time zones right when booking first-week meetings?", "The form collects location, and I map that to an IANA time zone such as Asia/Kolkata. A free-text offset would break on daylight-saving changes for overseas hires. The start date is a local date in the hire's zone. I build event start times in that zone and pass the time zone explicitly to the Google Calendar node, not rely on the n8n instance's default zone. Attendees in other zones see the converted time automatically. I also check the slots against working hours in both the hire's zone and the manager's zone. Meeting times go back to the orchestrator with the zone included, so the welcome message states times the hire will read correctly."),
    s(3, "What happens if the manager or buddy is busy at the proposed meeting time?", "Before creating events, the meetings sub-workflow checks free/busy for each attendee in the first-week window. Depending on the setup, that uses the Google Calendar node's availability operation or an HTTP Request to the free/busy API. It picks the first slot that works for everyone within working hours after the start time. If no slot fits, it does not double-book. It marks the meeting task as needing attention and posts to HR, so a human can resolve it. Created event IDs are stored in Postgres, so a rerun updates existing events instead of creating duplicate invites."),
    s(4, "HR can edit the AI draft in the approval form. What risks does that create and how do you handle them?", "The edited text becomes the message that is sent, so the approval step must store exactly what HR approved. It must not regenerate the draft afterwards. I save the approved text, the approver and a timestamp in Postgres, and Gmail sends that stored version unchanged. The risk is that HR adds a typo in a date, or that a long approval delay leaves the facts out of date because a meeting moved. Before sending, a Code node checks that the start date and meeting times in the approved text still match Postgres. If they do not, it sends the draft back for re-approval instead of sending stale facts. Every send is tied to one approval record."),
    s(3, "What if HR never clicks the approval link?", "The approval Wait node has a time limit that depends on how far away the start date is. If it expires, the workflow reminds HR in Slack, and after that escalates to an HR-ops channel. It never sends the message by default. Silence must not count as approval, because the rule is that nothing unapproved goes out. If the start date passes without approval, the welcome email is simply skipped and marked as such in Postgres. The day-one Slack DM is held as well. Account activation and meetings are not blocked by this, because they do not depend on the welcome message."),
    s(3, "Why send the welcome email to the personal address rather than the new work email?", "Before the start date, the new hire cannot log in to the work account. It is suspended until day one so that access is not granted early. So mail sent there would sit unread. The personal email is the address the hire actually checks. The trade-off is that the personal email is personal data, so it is used only for this send and the e-sign envelope. It is not included in the AI prompt, Slack summaries or error alerts. From day one, communication moves to the work identity, which is why the Slack DM is scheduled for the start date."),
    s(4, "Give a rough scaling estimate for this workflow. Do you expect load problems?", "I would estimate from the hiring rate, not guess numbers. Each hire creates one orchestrator execution plus three or four sub-workflow executions, a few approval and e-sign waits, one model call, and a handful of API calls to Workspace, Slack and Calendar. Even for a company hiring hundreds of people a month, that is a low and bursty volume. The real pressure points are bursts, such as a campus batch joining on the same day, which can hit Google or Slack rate limits, and long-waiting executions. A single n8n instance usually handles this. I would batch bulk imports with Loop Over Items and rely on retries with back-off rather than adding infrastructure."),
    s(3, "When would you move this to n8n queue mode, and what changes?", "I would move when executions start competing, for example when large batch joins run alongside other company workflows on the same instance, or when we need high availability. In queue mode, the main instance receives triggers and webhooks and puts executions on a Redis queue, and worker processes run them. Workers can scale horizontally. For this workflow, the design already suits that. State lives in Postgres, not in any one process, and idempotent upserts protect against two workers touching the same hire. Waiting executions are stored in the database, so they resume correctly regardless of which worker picks them up. I would also tune worker concurrency to stay under API rate limits."),
    s(4, "Two HR people submit the same hire within seconds of each other. How do you prevent a race?", "An IF node that reads 'does this hire exist?' is not enough. Both executions can read 'no' before either one writes. The guarantee has to come from Postgres. I use a primary key on hire_id and an INSERT ... ON CONFLICT upsert. Each task is then claimed with a conditional update, for example setting the status to in_progress only where it is pending, and checking that one row was affected. Only the execution that wins the claim creates the account. The other one sees the task is already in progress and stops or waits. For extra safety, the accounts step also looks up the user by work email in Workspace before creating it."),
    s(4, "What exactly should the error workflow do, and what should it avoid?", "Each onboarding workflow sets the same error workflow in its settings. That workflow starts with an Error Trigger, which receives the failed execution's details. It posts the hire ID, workflow name, failed node, a short error message and the execution link to the HR-ops Slack channel. It can also mark the task as failed in Postgres, so the status view shows the failure. It should avoid dumping the full item payload, because that would push personal email, location and document details into Slack. It should not try clever automatic fixes. The person handling it opens the execution, fixes the cause and reruns, and stored task status makes that rerun skip completed work."),
    s(4, "How do you decide between retry-on-fail and the error workflow?", "Retry-on-fail is for transient problems on a single node, such as a 429 rate limit, a 5xx from Google or Slack, or a network timeout. I set a few tries with a wait between them. It is only safe on operations that are idempotent or protected by a prior lookup, because a 'create user' call that timed out may actually have succeeded. The error workflow is for failures retries cannot fix: bad input, revoked credentials, a missing manager, or an exhausted retry budget. Those need a human. So retries absorb noise, and the error workflow makes the remaining failures visible with enough context to act on them."),
    s(4, "The Workspace user is created but adding the Slack account fails. What state are you in and how do you recover?", "This is a partial success, and the per-task status model is designed for it. The Workspace step writes 'done' with the user ID right after it succeeds. The Slack step is recorded separately, so its failure leaves that task as failed and the Workspace task untouched. The error workflow alerts HR-ops. When the rerun happens, the accounts sub-workflow sees the Workspace task is done, skips it, and retries only Slack. I would not roll back the Workspace user automatically. Deleting and recreating it adds risk and churn. The orchestrator also does not draft the welcome message until all account tasks it depends on are done."),
    s(4, "How do you secure the credentials this workflow uses?", "n8n stores credentials encrypted and nodes reference them by name, so secrets never appear in workflow JSON. On self-hosted instances, the encryption key is kept in a secret manager and backed up. Each credential is least-privilege. The Workspace service account can only manage users in the relevant organisational units. The Slack token has only the scopes needed to invite users and post messages. Calendar access is limited to the accounts doing the booking. The AI Gateway key is the only model credential, and no provider keys live in n8n. I restrict who can edit these workflows and see credentials, and I rotate keys when people leave the team."),
    s(4, "What personal data flows through this system, and how do you handle privacy?", "It holds the new hire's name, personal email, role, department, manager, start date and location, plus signed documents held by the e-sign provider. I apply data minimisation. The form collects only the fields later steps need. The AI prompt gets only the first name, role, team, start date and meeting times. No personal email or document content goes to the model. Slack messages and alerts carry the hire ID, not the full record. In India, the DPDP Act means we need a clear purpose and defined retention, so I would set execution-data pruning, limit who can view executions, and define how long Postgres keeps records after onboarding finishes."),
    s(3, "How would you choose the model and use gateway fallbacks for the welcome draft?", "The task is short, personalised writing with strict facts, so a capable general model such as anthropic/claude-sonnet-4.5 fits. The best choice is set by testing drafts against real examples, not by assumption. Because Vercel AI Gateway uses one OpenAI-compatible endpoint and one key, switching or comparing models means changing the model name, not adding credentials. I would configure a fallback model at the gateway, so an outage at one provider does not block drafts. Every draft still goes through HR approval, so a fallback model's tone is not a risk. The gateway's spend tracking shows the cost per draft over time."),
    s(4, "How would you test this workflow before using it on real new hires?", "I would use a separate n8n environment or project with sandbox credentials. That means a test Workspace organisational unit, a test Slack workspace, the e-sign provider's sandbox and a test calendar. I would use pinned data to replay form submissions through the orchestrator. The test cases are: a normal hire, a missing field, the same submission twice, two submissions at the same time, a forced Slack failure followed by a rerun, an e-sign timeout, an approval that never arrives, and a hire in another time zone. For the AI step, I keep a small set of inputs and check the drafts for correct facts. After launch, I would run the first few real hires with HR watching closely."),
    s(3, "How does HR get a single status view per hire, and what would you alert on?", "Postgres is the source of truth. The hire_tasks table shows each task's status, attempt count, last error and external references. HR can view it through a simple dashboard, a Google Sheets sync, or the manager's Slack summary when onboarding completes. n8n execution logs are for engineers, not HR. I would alert on any task in the failed state. I would also alert on tasks stuck in progress longer than expected, unsigned documents close to the start date, welcome drafts awaiting approval near day one, and an account not activated on the start date. These rules come from a scheduled check against Postgres, not only from node failures."),
    s(3, "The start date changes after onboarding has begun. How does the system handle it?", "Because the hire ID does not include the start date, a corrected submission maps to the same record. The orchestrator spots the changed field and marks the date-dependent tasks for redo: meetings, the welcome draft and approval, the day-one DM and the activation schedule. Accounts and e-sign are left as they are. Meetings uses the stored event IDs to move the existing events instead of creating new ones. A welcome message that was already sent cannot be recalled, so HR is asked to approve a short correction. Activation reads the start date from Postgres at run time, so it picks up the new date automatically."),
    s(3, "Would you keep the role-to-groups mapping in a Switch node or somewhere else?", "A Switch node is fine when there are a few stable roles. It is visible and easy to debug. But group and channel mappings change often, and each change would mean editing and redeploying the workflow. At larger scale, I would move the mapping into a Postgres table or a Google Sheet that HR or IT can maintain. The accounts sub-workflow would look up the role and department, with a Switch only for unknown roles, which go to a safe default with minimum access and an alert. That also creates an audit trail of who changed which access rule, which matters because this mapping decides what access people get."),
    s(3, "Execution logs contain personal data. How do you handle retention?", "n8n saves execution data by default, which helps debugging but keeps personal data in node inputs and outputs. I would turn on execution pruning with a defined maximum age. I would consider not saving successful executions for the most sensitive workflows, while keeping failed ones long enough to investigate. Access to view executions is limited to the operations team. Postgres task status, not execution logs, is the long-term record, so pruning loses nothing important. Sensitive values such as document links are kept out of fields that get logged where possible, and the retention periods are agreed with HR and legal, not chosen arbitrarily."),
    s(3, "How do you deploy changes to a sub-workflow without breaking hires that are already in flight?", "Waiting executions resume on the current saved version of the workflow. A careless edit to the e-sign sub-workflow could therefore break envelopes that are already waiting. I keep sub-workflow inputs and outputs as a stable contract: same field names, with new fields optional. I make backward-compatible changes, or create a new sub-workflow version that new hires call while old ones finish on the old version. Changes go through a test environment first, and workflows are exported to source control so we can review differences and roll back. Before deploying, I check Postgres for hires in progress to understand what a change could affect."),
    s(2, "Why use an n8n Form Trigger instead of integrating directly with an HRIS?", "The form is quick to build, needs no access to an HR system, and limits the input to exactly the fields needed. It suits a company without a mature HRIS or with a simple process. The trade-off is that HR types data twice and the system is only as accurate as that typing. That is why validation matters. If the company has an HRIS with webhooks or an API, triggering from the 'hire accepted' event removes re-typing and gives a natural hire ID. The rest of the design stays the same, because only the trigger and field mapping change. The orchestrator and sub-workflows do not depend on where the data came from."),
    s(3, "Why use an AI Agent for the welcome message rather than a fixed template?", "A template is deterministic, cheap and cannot get facts wrong. For many companies it is enough. AI helps when messages should vary by role, team and meeting plan, so they read naturally without HR maintaining many templates. The cost is that the output must be checked, which is why the prompt includes only the needed facts and HR approves every draft. A reasonable middle ground is to generate only the personalised paragraph with AI and keep dates and meeting times in template slots filled from Postgres. That removes most of the fact risk. I would decide based on whether HR values the personalisation enough to review each draft."),
    s(3, "The offer is withdrawn mid-onboarding. How do you unwind what has been done?", "A separate cancellation workflow, triggered by HR, reads the hire's tasks from Postgres and reverses only what exists, using the stored external IDs. It deletes or keeps suspended the Workspace user, removes the Slack invite, cancels the calendar events, voids the e-sign envelope through the provider's API, and stops any waiting executions. It also blocks pending sends: the approval and DM steps check the hire's overall status before sending, so a cancelled hire never gets a welcome. Each reversal is recorded per task, so the cancellation itself can be retried safely. Anything that cannot be undone automatically is flagged for HR to handle manually."),
  ],
  objective: [
    o(4, "Which trigger node starts a sub-workflow so that the orchestrator's Execute Workflow node can call it?", ["Webhook node","Execute Workflow Trigger (When Executed by Another Workflow)","Schedule Trigger","Chat Trigger"], 1, "A sub-workflow called through Execute Workflow starts with the Execute Workflow Trigger, which receives the items passed by the parent workflow."),
    o(4, "How should the orchestrator call the e-sign sub-workflow so it is not blocked for days?", ["Turn off the Execute Workflow node's 'wait for sub-workflow completion' option","Add a Wait node with a long timer in the orchestrator","Use a Merge node to wait for the signed status","Set retry-on-fail with a long wait between tries"], 0, "Without waiting for completion, the orchestrator continues straight away while the sub-workflow runs and waits on its own."),
    o(5, "What makes the Postgres hire record idempotent when the same hire is submitted twice?", ["A Code node that checks the execution ID","A unique key on hire_id with INSERT ... ON CONFLICT DO UPDATE","Creating a new row and deleting old ones each night","Storing records in workflow static data"], 1, "A unique key plus an upsert guarantees at the database level that one hire has one row, even when two submissions arrive at the same time."),
    o(5, "Which is the best basis for the stable hire ID?", ["A random UUID generated for each form submission","The n8n execution ID","A deterministic value such as an HR reference or a normalised personal email","The submission timestamp"], 2, "Only a deterministic ID maps a resubmission to the same hire; random, execution-based or time-based IDs create duplicates."),
    o(4, "Which node picks Google groups and Slack channels based on the hire's role?", ["Merge","Switch","Loop Over Items","Wait"], 1, "Switch sends items to different outputs based on a value such as role."),
    o(4, "How is the error workflow connected to the onboarding workflows?", ["Each node gets an extra output wired to Slack","Each workflow's settings name an error workflow that begins with an Error Trigger","The Form Trigger has an on-error field","Queue mode sends failures to Redis for alerts"], 1, "In n8n, a workflow's settings specify an error workflow, which starts with the Error Trigger node."),
    o(4, "For which failure is per-node retry-on-fail most appropriate?", ["A required field is missing from the form","Google Workspace returns a temporary 503 or rate-limit error","The Slack credential has been revoked","The manager named in the form does not exist"], 1, "Retries help with transient errors; bad data and broken credentials need a human through the error workflow."),
    o(3, "Which expression gives the URL that resumes a Wait node set to 'On webhook call'?", ["$json.webhookUrl","$execution.resumeUrl","$workflow.id","$node.url"], 1, "$execution.resumeUrl is the execution-specific URL that resumes a waiting execution."),
    o(3, "In this design, which model name format does the chat model sub-node send to Vercel AI Gateway?", ["claude-sonnet-4.5 with an Anthropic API key","anthropic/claude-sonnet-4.5","ai-gateway:claude","https://anthropic.com/claude-sonnet-4.5"], 1, "AI Gateway uses provider/model names such as anthropic/claude-sonnet-4.5 on one OpenAI-compatible endpoint."),
    o(3, "Where are the model providers' API keys stored in this blueprint?", ["In an n8n credential for each provider","Not in n8n; n8n holds only the AI Gateway API key","In the AI Agent's system prompt","In the Postgres hires table"], 1, "The gateway design keeps provider keys out of n8n and uses one AI Gateway key."),
    o(3, "What is a benefit of routing the welcome-draft model call through AI Gateway?", ["It removes the need for HR approval","It supports fallbacks and spend tracking across providers through one credential","It stores the hire's personal data for later prompts","It makes model output deterministic"], 1, "The gateway provides fallbacks, spend tracking and access to many providers with one key; it does not make output safe or deterministic."),
    o(3, "What does n8n queue mode need in order to send executions to workers?", ["Redis","Kafka","A vector store","Google Sheets"], 0, "n8n queue mode uses Redis as the message broker between the main instance and workers."),
    o(5, "When does Gmail send the welcome message to the new hire?", ["As soon as the AI Agent returns a draft","After the e-sign webhook arrives","Only after HR approves it through the Wait-for-form approval","On the start date whatever HR decides"], 2, "The rule is that no unapproved message is sent, so sending is gated on the approval form."),
    o(4, "Which set of fields belongs in the welcome-message prompt?", ["Full form payload including personal email and location","First name, role, team, start date and meeting times","Signed offer document text","Work email password and Slack token"], 1, "The prompt contains only the facts the message needs, to keep data exposure and error sources small."),
    o(3, "What is the Merge node's job in this workflow?", ["Removing duplicate hires","Combining the account and meeting results into one item for the AI Agent","Joining Postgres tables","Sending data to several sub-workflows at once"], 1, "Merge combines data from separate branches so the AI Agent gets the work email and the meeting times together."),
    o(5, "How should the design meet the rule 'never grant access before it is due'?", ["Create the user active and ask the hire not to log in","Create the account suspended or without services, and activate it with a scheduled job on the start date","Delay the whole orchestrator until the start date","Share the password only on day one"], 1, "Separating creation from activation lets the work email exist early while access begins only on the start date."),
    o(5, "After the error workflow fires and someone reruns onboarding, what prevents repeated work?", ["n8n automatically skips nodes that succeeded before","Per-task status in Postgres, checked before each task runs","Retry-on-fail on the Form Trigger","Deleting the failed execution"], 1, "Stored task status lets each step see it is already done and skip itself."),
    o(4, "How should the meetings sub-workflow handle time zones?", ["Use the n8n server's default time zone","Map location to an IANA time zone and pass it explicitly to Google Calendar","Always book in UTC and let the hire convert","Store times as plain text like '10am'"], 1, "An explicit IANA zone handles daylight saving and avoids depending on the server's setting."),
    o(3, "HR uploads a batch of 200 campus hires. Which node helps process them in controlled groups to respect API rate limits?", ["Loop Over Items","IF","Set/Edit Fields","Chat Trigger"], 0, "Loop Over Items processes items in batches, which helps control pressure on Google and Slack APIs."),
    o(3, "How does n8n store credentials such as the Workspace service account?", ["In plain text inside workflow JSON","Encrypted, and referenced by nodes","Only in environment variables on each worker","Inside Code node source"], 1, "n8n encrypts stored credentials, and nodes reference them without exposing the secrets."),
    o(2, "Which languages can the Code node run in n8n?", ["JavaScript or Python","Only SQL","Go or Rust","Only JSONata"], 0, "The Code node supports JavaScript and Python."),
    o(4, "What should the Error Trigger alert to HR-ops contain?", ["The full item payload with personal email and location","Hire ID, failed node and execution link","Only the word 'failed'","The decrypted credential that failed"], 1, "This gives enough context to act without pushing personal data or secrets into Slack."),
    o(4, "An e-sign webhook arrives. What should be checked before the sub-workflow marks documents as signed?", ["Nothing, because the URL is secret","That it is verified, the envelope ID matches the stored hire, and the event means completed","Only that the HTTP method is POST","That the AI Agent agrees"], 1, "Verification and matching the envelope ID stop forged, mismatched or 'viewed' events from setting the signed status."),
    o(3, "A Wait node for signing has a time limit set. What happens when the limit passes without a webhook?", ["The execution is deleted","The execution resumes, so the workflow can check status and send a reminder","n8n retries the e-sign request automatically","The error workflow always fires"], 1, "With a time limit, the Wait node resumes after the limit, which lets the workflow take the reminder path."),
    o(4, "Two identical submissions run at the same moment. Why is an IF node 'hire exists?' check not enough?", ["IF nodes cannot read Postgres results","Both executions may read 'not found' before either writes; only a database constraint or atomic claim prevents it","IF nodes run only in queue mode","IF nodes ignore JSON"], 1, "A check followed by a separate write is a race; atomic database operations close the gap."),
    o(3, "Why is retry-on-fail on a 'create user' call risky without a prior lookup?", ["Retries are not supported on app nodes","A timed-out call may have succeeded, so a blind retry can create a duplicate","Retries leak credentials","Retries pause the workflow for days"], 1, "Non-idempotent creates need a lookup or idempotency guard so a retry cannot duplicate the account."),
    o(2, "Which deployment options does n8n offer?", ["Only n8n Cloud","Self-hosted or n8n Cloud","Only a desktop app","Only as a Vercel function"], 1, "n8n is fair-code and can be self-hosted or used on n8n Cloud."),
    o(3, "How can the day-one Slack DM be sent on the start date?", ["Send it immediately and ask Slack to delay it","Use a Wait node set to resume at a specified time, or a scheduled workflow that reads start dates from Postgres","Put the start date in the AI prompt","Use retry-on-fail with a long wait"], 1, "Waiting until a set time or scheduling from stored dates delivers the DM on day one."),
    o(2, "HR adds a free-text note to a hire. Which n8n AI node pulls structured fields from it?", ["Information Extractor","Embeddings","Merge","Schedule Trigger"], 0, "The Information Extractor node turns unstructured text into structured fields."),
    o(3, "Which change to a running sub-workflow is safest for hires already waiting on a Wait node?", ["Renaming the fields other workflows expect","A backward-compatible change that keeps the input and output fields stable","Deleting and recreating the sub-workflow","Changing its trigger type"], 1, "Waiting executions resume on the current version, so the input/output contract must stay compatible."),
  ],
};
export default bank;
